window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-bd1d9121c3dc5224"]={"versions": [{"id": "FIG-bd1d9121c3dc5224", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des dynamischen Ablaufs für den Zustandswechsel der Firewall (Szenario „Switch Firewall State“) im Security-Subsystem der AUTOSAR Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die Anwendungsinstanz <code>:Adaptive Application</code> (als Akteur dargestellt), das funktionale Cluster <code>:Firewall</code> mit dem Stereotyp <code>«aapFunctionalCluster»</code> sowie die Plattform-Laufzeitumgebung <code>:Operating System</code> (als Akteur dargestellt). Schnittstellen-Operationen umfassen den synchronen Aufruf <code>SwitchFirewallState()</code> an das Cluster <code>:Firewall</code> sowie den nachgelagerten synchronen Aufruf <code>applyRule()</code> an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die <code>:Adaptive Application</code> initiiert den Zustandswechsel über den synchronen Methodenaufruf <code>SwitchFirewallState()</code> an <code>:Firewall</code>. Innerhalb eines kombinierten Fragments vom Typ <code>loop</code> mit der Bedingung <code>[foreach FirewallRule]</code> ruft <code>:Firewall</code> für jede anzuwendende Firewall-Regel synchron die Operation <code>applyRule()</code> auf dem <code>:Operating System</code> auf. Nach Abarbeitung der Regelschleife erfolgt die synchrone Rückkehr (gestrichelte Antwortnachricht) von <code>:Firewall</code> an die <code>:Adaptive Application</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das Zusammenspiel zwischen einer Adaptive Application, dem Firewall-Cluster und den Paketfilter- bzw. Netzwerkkonfigurationsfunktionen des zugrunde liegenden Betriebssystems. Entwickler müssen beachten, dass das Schalten des Firewall-Zustands blockierend ausgeführt wird und die Regelsätze sequenziell auf Betriebssystemebene angewendet werden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0a8bb22a36753ced", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des dynamischen Ablaufs für den Zustandswechsel der Firewall (Szenario „Switch Firewall State“) im Security-Subsystem der AUTOSAR Adaptive Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Entitäten sind die Anwendungsinstanz <code>:Adaptive Application</code> (als Akteur dargestellt), das funktionale Cluster <code>:Firewall</code> mit dem Stereotyp <code>«aapFunctionalCluster»</code> sowie die Plattform-Laufzeitumgebung <code>:Operating System</code> (als Akteur dargestellt). Schnittstellen-Operationen umfassen den synchronen Aufruf <code>SwitchFirewallState()</code> an das Cluster <code>:Firewall</code> sowie den mit dem Stereotyp <code>«aapInformative»</code> gekennzeichneten synchronen Aufruf <code>applyRule()</code> an das Betriebssystem.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die <code>:Adaptive Application</code> initiiert den Zustandswechsel über den synchronen Methodenaufruf <code>SwitchFirewallState()</code> an <code>:Firewall</code>. Innerhalb eines kombinierten Fragments vom Typ <code>loop</code> mit der Bedingung <code>[foreach FirewallRule]</code> ruft <code>:Firewall</code> für jede anzuwendende Firewall-Regel synchron die Operation <code>applyRule()</code> auf dem <code>:Operating System</code> auf. Nach Abarbeitung der Regelschleife erfolgt die synchrone Rückkehr (gestrichelte Antwortnachricht) von <code>:Firewall</code> an die <code>:Adaptive Application</code>.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das Zusammenspiel zwischen einer Adaptive Application, dem Firewall-Cluster und den Paketfilter- bzw. Netzwerkkonfigurationsfunktionen des zugrunde liegenden Betriebssystems. Der mit <code>«aapInformative»</code> gekennzeichnete Aufruf <code>applyRule()</code> verdeutlicht, dass die konkrete Betriebssystemschnittstelle informativen Charakter besitzt und implementationsabhängig sein kann, während der Zustandswechsel über <code>SwitchFirewallState()</code> blockierend ausgeführt wird.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-bd1d9121c3dc5224", "to": "FIG-0a8bb22a36753ced", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Am synchronen Aufruf <code>applyRule()</code> vom Functional Cluster <code>:Firewall</code> an <code>:Operating System</code> wurde die Stereotyp-Auszeichnung <code>«aapInformative»</code> ergänzt.\n</li></ul>"}]};
